package com.company.tpm.attendance;import jakarta.validation.constraints.NotNull;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/attendance")public class AttendanceController{private final AttendanceService service;AttendanceController(AttendanceService s){service=s;}public record Request(@NotNull UUID sessionId,@NotNull UUID employeeId,@NotNull Attendance.Status status,String remark){}@PostMapping @PreAuthorize("hasAuthority('attendance.record')")void record(@RequestBody Request r,Authentication a){service.record(r.sessionId(),r.employeeId(),r.status(),a.getName(),r.remark());}}
